function historicalLaunchSeries(metric: "attempts" | "success") {
  const points = historicalSeries.launchActivity as HistoricalLaunchPoint[];
  return { years: points.map((point) => point.label), us: points.map((point) => point[metric].us), cn: points.map((point) => point[metric].cn), other: points.map((point) => point[metric].other), global: points.map((point) => point[metric].global) };
}

function payloadFlowSeries(mode: "mass" | "mass-per-launch") {
  const flow = historicalSeries.payloadFlow;
  const launches = historicalSeries.launchActivity;
  const regions = ["us", "cn", "other", "global"] as const;
  const values = Object.fromEntries(regions.map((region) => [region, flow.map((point, index) => {
    const tonnes = point.knownDeliveredMassKg[region] / 1e3;
    return mode === "mass" ? tonnes : launches[index].success[region] ? tonnes / launches[index].success[region] : null;
  })])) as Record<(typeof regions)[number], Array<number | null>>;
  return { years: flow.map((point) => point.label), ...values };
}

